count_errors() {
  grep -i "error" "$1" | sort | uniq -c | sort -rn | head -n 5
}

if [ -f app.log ]; then
  count_errors app.log
fi

#!/usr/bin/env bash
set -euo pipefail

trap 'echo "failed on line $LINENO"' ERR

case "$1" in
  start) echo "starting" ;;
  stop)  echo "stopping" ;;
  *)     echo "usage: $0 {start|stop}" ;;
esac

greet() {
  local name="$1"
  echo "Hello, $name!"
}

greet "Ann"

while getopts "f:v" opt; do
  case $opt in
    f) file="$OPTARG" ;;
    v) verbose=1 ;;
    *) exit 1 ;;
  esac
done
